/**
 * Executes in the worker thread.
 * @param {import('piper-timing-farm-browser').AudioSynthesisResult} result - The raw synthesis output.
 * @returns {string[]} The list of phonemes.
 */
export function extractPhonemes(result) {
  console.log('[Worker Callback] Extracting phonemes...');
  // The result.metadata already contains the phonemes generated by the phonemizer.
  return result.metadata.phonemes || [];
}
